package ais.action.master.sosial.helper;

import java.math.BigDecimal; import java.util.Date; import org.hibernate.LockMode; import org.hibernate.Session; import org.hibernate.Transaction; import ais.database.hibernate.HibernateUtil; import ais.database.model.sosial.*;

public final class SocialDistributionService {
 public DetailPenyaluranDonasi post(SocialRequestContext c,Long detailId){new SocialPrivilegeGuard().require(c,SocialPrivilegeGuard.FINANCE);Session s=null;Transaction tx=null;try{s=HibernateUtil.openSession();tx=s.beginTransaction();DetailPenyaluranDonasi d=(DetailPenyaluranDonasi)s.get(DetailPenyaluranDonasi.class,detailId);if(d==null||!c.getTenantKey().equals(d.getTenantKey()))throw new IllegalArgumentException("Penyaluran tidak ditemukan.");SocialStateMachine.requireDistribution(d.getApprovalStatus(),"POSTED");AlokasiDonasi a=d.getSourceAllocation();s.lock(a,LockMode.UPGRADE);if(!c.getTenantKey().equals(a.getTenantKey()))throw new SecurityException("Tenant alokasi tidak cocok.");if(!"POSTED".equals(a.getStatus()))throw new IllegalStateException("Sumber alokasi belum posted.");BigDecimal used=(BigDecimal)s.createQuery("select sum(x.amount) from DetailPenyaluranDonasi x where x.sourceAllocation=:a and x.status='POSTED'").setEntity("a",a).uniqueResult();if(used==null)used=BigDecimal.ZERO;if(d.getAmount()==null||d.getAmount().signum()<=0)throw new IllegalStateException("Nominal penyaluran tidak valid.");if(used.add(d.getAmount()).compareTo(a.getAmount())>0)throw new IllegalStateException("Penyaluran melebihi saldo alokasi.");String compatible=d.getBeneficiaryCategory().getCompatibleFundCodes();if(Boolean.TRUE.equals(d.getFundType().getRestricted())&&(compatible==null||!(","+compatible.toUpperCase()+",").contains(","+d.getFundType().getKode().toUpperCase()+",")))throw new IllegalStateException("Kategori penerima tidak kompatibel dengan dana restricted.");d.setStatus("POSTED");d.setApprovalStatus("POSTED");d.setUpdatedBy(c.getActorId());if(d.getDistributionDate()==null)d.setDistributionDate(new Date());tx.commit();return d;}catch(RuntimeException e){if(tx!=null)try{tx.rollback();}catch(Exception ignored){}throw e;}finally{if(s!=null)try{s.close();}catch(Exception ignored){}}}
}
